LOCAL_STATE = {
    "graph": ".dev-graph/state/graph.json",
    "cache": ".dev-graph/cache",
    "locks": ".dev-graph/locks",
}
LOCAL_DIRS = [".dev-graph", ".dev-graph/state", ".dev-graph/cache", ".dev-graph/locks", ".dev-graph/templates"]
HOOK_EVENTS = {"PreToolUse", "SessionStart", "PostToolUse", "TaskCompleted"}
SECRET_KEY_HINTS = ("token", "secret", "password", "credential", "node_id", "nodeid", "item_id", "field_id")


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run_json(argv: list[str]) -> tuple[int, Any, str]:
    env = dict(os.environ)
    env.pop("CLAUDE_PROJECT_DIR", None)
    cp = subprocess.run(argv, cwd=str(SCRIPTS), text=True, capture_output=True, env=env)
    try:
        payload = json.loads(cp.stdout)
    except json.JSONDecodeError:
        payload = None
    return cp.returncode, payload, cp.stderr.strip()


# --- R1: caller repository context -------------------------------------------------
def r1_context(repo_root: str) -> dict[str, Any]:
    code, receipt, err = run_json(
        ["python3", "resolve-repo-context.py", "--repo-root", repo_root, "--mode", "write"]
    )
    if code != 0 or not isinstance(receipt, dict):
        raise SystemExit(f"R1 fail-closed: resolve-repo-context exit={code}: {err}")
    root = Path(receipt["repo_root"])
    if root.resolve(strict=True) != Path(receipt["content_roots"]["repository"]).resolve(strict=True):
        raise SystemExit("R1 fail-closed: repo_root != content_roots.repository")
    toplevel = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "--show-toplevel"], text=True, capture_output=True
    ).stdout.strip()
    if Path(toplevel).resolve(strict=True) != root.resolve(strict=True):
        raise SystemExit("R1 fail-closed: host project root mismatch")
    plugin_source = Path(receipt["plugin_source"]).resolve(strict=True)
    if plugin_source == root.resolve(strict=True) or str(plugin_source).startswith(str(root.resolve()) + os.sep):
        raise SystemExit("R1 fail-closed: plugin source must stay outside content authority")
    return receipt


