INITIAL_GRAPH = {"schema_version": "1.0.0", "nodes": []}


def r2_plan(root: Path, repository_id: str) -> dict[str, Any]:
    plan: dict[str, Any] = {"directories": [], "files": [], "templates": [], "hooks": {}}
    for relative in sorted(set(CONTENT_ROOTS.values())):
        plan["directories"].append({"path": relative, "role": "content_root", "exists": (root / relative).is_dir()})
    for relative in LOCAL_DIRS:
        plan["directories"].append({"path": relative, "role": "repo_local", "exists": (root / relative).is_dir()})
    plan["files"].append(
        {"path": ".dev-graph/config.json", "role": "repo_config",
         "content": repo_config(repository_id), "exists": (root / ".dev-graph/config.json").is_file()}
    )
    plan["files"].append(
        {"path": LOCAL_STATE["graph"], "role": "graph_store",
         "content": INITIAL_GRAPH, "exists": (root / LOCAL_STATE["graph"]).is_file()}
    )
    for source in sorted((PLUGIN_ROOT / "templates").iterdir()):
        if not source.is_file():
            continue
        target = root / ".dev-graph/templates" / source.name
        entry = {"name": source.name, "source_digest": sha256_file(source), "exists": target.is_file()}
        entry["target_digest"] = sha256_file(target) if target.is_file() else None
        if not entry["exists"]:
            entry["decision"] = "copy"
        elif entry["target_digest"] == entry["source_digest"]:
            entry["decision"] = "preserve_identical"
        else:
            entry["decision"] = "preserve_user_modified"
        plan["templates"].append(entry)
    plan["hooks"] = r5_hooks_plan(root)
    plan["planned_changes"] = (
        [d["path"] for d in plan["directories"] if not d["exists"]]
        + [f["path"] for f in plan["files"] if not f["exists"]]
        + [f".dev-graph/templates/{t['name']}" for t in plan["templates"] if t["decision"] == "copy"]
        + plan["hooks"]["planned_writes"]
    )
    return plan


# --- R5: hook wiring ---------------------------------------------------------------
def r5_hooks_plan(root: Path) -> dict[str, Any]:
    plugin_hooks_path = PLUGIN_ROOT / "hooks" / "hooks.json"
    plugin_hooks = json.loads(plugin_hooks_path.read_text(encoding="utf-8")).get("hooks", {})
    settings = root / ".claude" / "settings.json"
    existing = json.loads(settings.read_text(encoding="utf-8")) if settings.is_file() else None
    project_dev_graph_entries = 0
    if isinstance(existing, dict):
        blob = json.dumps(existing.get("hooks", {}), ensure_ascii=False)
        project_dev_graph_entries = blob.count("dev-graph")
    return {
        "requested_source": "plugin",
        "effective_source": "plugin",
        "plugin_hook_events": sorted(plugin_hooks),
        "plugin_hook_events_complete": set(plugin_hooks) == HOOK_EVENTS,
        "project_settings_present": settings.is_file(),
        "project_settings_digest": sha256_file(settings) if settings.is_file() else None,
        "project_fallback_entries": project_dev_graph_entries,
        "double_registration": project_dev_graph_entries > 0,
        "planned_writes": [],
        "rollback_manifest_required": False,
        "diagnostic": "plugin hook is effective; project fallback is refused by contract",
    }


# --- R3/R4: apply ------------------------------------------------------------------
def apply(root: Path, plan: dict[str, Any], dry_run: bool) -> dict[str, Any]:
    created: list[str] = []
    preserved: list[str] = []
    migration_preview: list[dict[str, Any]] = []
    for entry in plan["directories"]:
        target = root / entry["path"]
        if entry["exists"]:
            preserved.append(entry["path"])
            continue
        if not dry_run:
            target.mkdir(parents=True, exist_ok=True)
        created.append(entry["path"])
    for entry in plan["files"]:
        target = root / entry["path"]
        if entry["exists"]:
            preserved.append(entry["path"])
            continue
        if not dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(
                json.dumps(entry["content"], ensure_ascii=False, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
        created.append(entry["path"])
    for entry in plan["templates"]:
        relative = f".dev-graph/templates/{entry['name']}"
        source = PLUGIN_ROOT / "templates" / entry["name"]
        target = root / relative
        if entry["decision"] == "copy":
            if not dry_run:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(source.read_bytes())
            created.append(relative)
        elif entry["decision"] == "preserve_identical":
            preserved.append(relative)
        else:
            preserved.append(relative)
            migration_preview.append(
                {
                    "path": relative,
                    "reason": "user_modified_template_not_overwritten",
                    "repo_digest": entry["target_digest"],
                    "plugin_digest": entry["source_digest"],
                    "template_version": "1.0.0",
                }
            )
    return {"created": sorted(created), "preserved": sorted(preserved), "migration_preview": migration_preview}


# --- verification ------------------------------------------------------------------
def config_findings(root: Path, config: dict[str, Any], repository_id: str) -> list[str]:
    from validate_shim import validate_config  # type: ignore

    findings = validate_config(config)
    if config.get("repository_id") != repository_id:
        findings.append("repository_id does not match the C24 receipt")

    def walk(value: Any, path: str) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                if any(hint in key.lower() for hint in SECRET_KEY_HINTS):
                    findings.append(f"forbidden key stores secret/node id: {path}.{key}")
                walk(child, f"{path}.{key}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, f"{path}[{index}]")
        elif isinstance(value, str):
            if value.startswith("/") or value.startswith("~") or "\\" in value or str(root) in value:
                findings.append(f"absolute or host-specific path stored at {path}: {value}")
            if value.startswith(("ghp_", "gho_", "github_pat_", "PVT_", "PVTI_", "PVTF_", "I_kw", "MDU6")):
                findings.append(f"token or GitHub node id stored at {path}")

    walk(config, "$")
    return findings


def template_findings(root: Path) -> list[str]:
    contract = json.loads((PLUGIN_ROOT / "templates" / "template-contract.json").read_text(encoding="utf-8"))
    required = {contract["common_frontmatter"]["template"], "template-contract.json",
                contract["graph_projection"]["template"]}
    for artifact in contract["artifacts"].values():
        required.add(artifact["template"])
        required.update((artifact.get("conditional_templates") or {}).values())
        required.update((artifact.get("subtype_templates") or {}).values())
    required.add(contract["system_plan"]["task_overlay"])
    findings = []
    for name in sorted(required):
        if not (root / ".dev-graph/templates" / name).is_file():
            findings.append(f"template asset missing: {name}")
    return findings


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--hook-source", default="plugin", choices=("plugin", "project-fallback"))
    parser.add_argument("--run-label", required=True)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    receipt = r1_context(args.repo_root)
    root = Path(receipt["repo_root"])
    plan = r2_plan(root, receipt["repository_id"])
    if args.hook_source == "project-fallback" and plan["hooks"]["effective_source"] == "plugin":
        raise SystemExit("R5 fail-closed: project fallback refused while plugin hook is effective")
    outcome = apply(root, plan, args.dry_run)

    config_path = root / ".dev-graph/config.json"
    config = json.loads(config_path.read_text(encoding="utf-8")) if config_path.is_file() else {}
    code, report, err = run_json(
        ["python3", "validate-graph-schema.py", "--graph", str(root / LOCAL_STATE["graph"]),
         "--repo-root", str(root)]
    )
    if report is None:
        raise SystemExit(f"C11 gate could not run: {err}")

    checks = {
        "six_content_roots_exist": all((root / name).is_dir() for name in SIX_CONTENT_ROOTS),
        "system_spec_root_exists": (root / "system-spec").is_dir(),
        "repo_local_dirs_exist": all((root / name).is_dir() for name in LOCAL_DIRS),
        "config_exists": config_path.is_file(),
        "graph_exists": (root / LOCAL_STATE["graph"]).is_file(),
        "config_findings": config_findings(root, config, receipt["repository_id"]) if config else ["config missing"],
        "template_findings": template_findings(root),
        "c11_exit_code": code,
        "c11_valid": bool(report.get("valid")),
        "hook_single_path": plan["hooks"]["effective_source"] == "plugin" and not plan["hooks"]["double_registration"],
        "hook_events_complete": plan["hooks"]["plugin_hook_events_complete"],
        "project_settings_untouched": plan["hooks"]["planned_writes"] == [],
    }
    result = {
        "run_label": args.run_label,
        "dry_run": args.dry_run,
        "repository_id": receipt["repository_id"],
        "worktree_id": receipt["worktree_id"],
        "root_trust_evidence": receipt["root_trust_evidence"],
        "content_roots": {key: value for key, value in CONTENT_ROOTS.items()},
        "local_state": dict(LOCAL_STATE),
        "planned_changes": plan["planned_changes"],
        "planned_change_count": len(plan["planned_changes"]),
        "created": outcome["created"],
        "preserved_count": len(outcome["preserved"]),
        "migration_preview": outcome["migration_preview"],
        "template_decisions": {
            entry["name"]: entry["decision"] for entry in plan["templates"]
        },
        "hook_source": plan["hooks"],
        "schema_result": {
            "c11_exit_code": code,
            "valid": report.get("valid"),
            "violations": report.get("violations"),
            "implementation_readiness": report.get("implementation_readiness"),
        },
        "checks": checks,
    }
    print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

